SELECT CASE WHEN rating >= 3.5 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(*) FILTER (WHERE country = 'US') AS us_rows, COUNT_IF(city = 'Singapore') AS singapore_events, STDDEV_SAMP(rating) AS rating_stddev, COUNT(*) AS row_count FROM suppliers GROUP BY CASE WHEN rating >= 3.5 THEN 'HIGH' ELSE 'LOW' END ORDER BY rating_tier ASC NULLS FIRST
